<?php defined('BASEPATH') OR exit('No direct script access allowed');class Webhook extends MY_Controller{function __construct(){parent::__construct();$this->load->model('Webhook_model','hooks');}function inbound($source=NULL){if($this->input->method(TRUE)==='POST'){if(!$source)return $this->fail('NOT_FOUND','Webhook source required',404);$secret=(string)getenv('VP_WEBHOOK_SECRET');$provided=$this->input->get_request_header('X-Windels-Webhook-Secret',TRUE);$verified=$secret!==''&&is_string($provided)&&(hash_equals($secret,$provided)||hash_equals('sha256='.$secret,$provided));if(!$verified)return $this->fail('UNAUTHORIZED','Invalid webhook signature',401);$org=$this->input->get_request_header('X-Windels-Organization-Id',TRUE);$payload=json_decode($this->input->raw_input_stream,TRUE);if(!is_array($payload))return $this->fail('VALIDATION_ERROR','JSON object payload required',422);$r=$this->hooks->receive($org,$source,$payload,TRUE,$payload['eventType']??NULL);return $r?$this->respond($r,201):$this->fail('NOT_FOUND','Organization not found',404);}$c=$this->require_auth();if(!$c)return;$p=max(1,(int)$this->input->get('page'));$pp=min(100,max(1,(int)($this->input->get('perPage')?:25)));return $this->respond($this->hooks->listing($c['organizationId'],$this->input->get('source'),$this->input->get('status'),$p,$pp));}function item($id){$c=$this->require_auth();if(!$c)return;if($this->input->method(TRUE)==='DELETE'){if($this->hooks->remove($id,$c['organizationId'])){$this->output->set_status_header(204);return;}return $this->fail('NOT_FOUND','Inbox entry not found in organization',404);}$r=$this->hooks->one($id,$c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Inbox entry not found in organization',404);}function replay($id){$c=$this->require_auth();if(!$c)return;$r=$this->hooks->replay($id,$c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Inbox entry not found in organization',404);}function billing(){if($this->input->method(TRUE)!=='POST')return $this->fail('METHOD_NOT_ALLOWED','POST required',405);return $this->inbound('billing');}}
